import React, { useCallback, useEffect, useState } from 'react';
import {
  Bar,
  BarChart,
  CartesianGrid,
  Legend,
  ResponsiveContainer,
  Tooltip,
  XAxis,
  YAxis,
} from 'recharts';
import {
  Button,
  FormActions,
  Input,
  dispatchAppToast,
} from '@linm-soft-org/linm-web-common-components';
import { Spin, Text, Title } from '@/components/common';
import { useAppDispatch } from '../../../store/hooks';
import { fpcService } from '../../../services/fpc/service';
import type { ThirteenWeekCashflowDto } from '../../../services/fpc/types';
import { useFpcPermissions } from '../../../utils/fpcPermissionCode';
import styles from './ThirteenWeekCashflowPage.module.css';

const TEST_ID = 'thirteen-week';

const fVnd = (v: number): string =>
  new Intl.NumberFormat('vi-VN', { style: 'currency', currency: 'VND', maximumFractionDigits: 0 }).format(v);

const fCompact = (v: number): string => {
  const abs = Math.abs(v);
  const sign = v < 0 ? '-' : '';
  if (abs >= 1_000_000_000) return `${sign}${(abs / 1_000_000_000).toFixed(1)} tỷ`;
  if (abs >= 1_000_000) return `${sign}${(abs / 1_000_000).toFixed(0)} tr`;
  if (abs >= 1_000) return `${sign}${(abs / 1_000).toFixed(0)} ng`;
  return `${v.toLocaleString('vi-VN')}`;
};

const chartCurrency = (v: number): string => `${(v / 1_000_000).toFixed(0)}tr`;

function todayLocalYmd(): string {
  const d = new Date();
  const y = d.getFullYear();
  const m = String(d.getMonth() + 1).padStart(2, '0');
  const day = String(d.getDate()).padStart(2, '0');
  return `${y}-${m}-${day}`;
}

function formatDisplayDate(isoOrYmd?: string | null): string {
  if (!isoOrYmd) return '—';
  const raw = isoOrYmd.slice(0, 10);
  const [y, m, d] = raw.split('-');
  if (!y || !m || !d) return isoOrYmd;
  return `${d}/${m}/${y}`;
}

const ThirteenWeekCashflowPage: React.FC = () => {
  const dispatch = useAppDispatch();
  const { canView13Week, canExportReports } = useFpcPermissions();

  const defaultEnd = todayLocalYmd();
  const [endDate, setEndDate] = useState(defaultEnd);
  const [appliedEnd, setAppliedEnd] = useState(defaultEnd);
  const [data, setData] = useState<ThirteenWeekCashflowDto | null>(null);
  const [loading, setLoading] = useState(true);
  const [loadError, setLoadError] = useState(false);

  const loadReport = useCallback(async (asOf: string) => {
    setLoading(true);
    setLoadError(false);
    try {
      const result = await fpcService.get13WeekReport({ endDate: asOf });
      setData(result);
      setAppliedEnd(asOf);
    } catch {
      setData(null);
      setLoadError(true);
      dispatchAppToast(dispatch, {
        message: 'Không thể tải báo cáo dòng tiền 13 tuần',
        type: 'error',
      });
    } finally {
      setLoading(false);
    }
  }, [dispatch]);

  useEffect(() => {
    const t = window.setTimeout(() => {
      void loadReport(appliedEnd);
    }, 0);
    return () => window.clearTimeout(t);
    // eslint-disable-next-line react-hooks/exhaustive-deps -- initial load; Xem/Làm mới gọi loadReport
  }, []);

  const handleView = () => {
    if (!endDate) {
      dispatchAppToast(dispatch, { message: 'Vui lòng chọn ngày xem', type: 'error' });
      return;
    }
    void loadReport(endDate);
  };

  const handleRefresh = () => {
    void loadReport(appliedEnd);
  };

  if (!canView13Week) {
    return (
      <div className={styles.page} data-testid={`${TEST_ID}-page`}>
        <div className={styles.empty}>
          <Text type="secondary">Bạn không có quyền xem dòng tiền 13 tuần.</Text>
        </div>
      </div>
    );
  }

  const weeks = data?.weeks ?? [];
  const chartRows = weeks.map(w => ({
    ...w,
    chartLabel: `W${w.weekNumber}`,
  }));
  const maxGap = data?.maxFundingGap ?? 0;
  const gapWeeks = data?.gapWeeks ?? 0;

  return (
    <div className={styles.page} data-testid={`${TEST_ID}-page`}>
      <div className={styles.headerCard}>
        <div className={styles.headerTop}>
          <div>
            <Title level={4}>
              <i className="fas fa-chart-bar" style={{ marginRight: 8, color: '#2563eb' }} />
              Dòng tiền 13 tuần
            </Title>
            <Text type="secondary">
              Roll-up O/I/F · khoảng trống vốn
              {appliedEnd ? ` · Ngày xem: ${formatDisplayDate(appliedEnd)}` : ''}
            </Text>
          </div>
          <FormActions align="end">
            <Button onClick={handleRefresh} data-testid={`${TEST_ID}-refresh-btn`}>
              <i className="fas fa-redo" /> Làm mới
            </Button>
            {canExportReports && (
              <Button
                variant="secondary"
                disabled={!data}
                onClick={() => window.print()}
                data-testid={`${TEST_ID}-export-btn`}
              >
                <i className="fas fa-print" /> In
              </Button>
            )}
          </FormActions>
        </div>

        <div className={styles.filterRow}>
          <div className={styles.filterField}>
            <label className={styles.filterLabel} htmlFor={`${TEST_ID}-end-date`}>Ngày xem</label>
            <Input
              id={`${TEST_ID}-end-date`}
              type="date"
              value={endDate}
              onChange={e => setEndDate(e.target.value)}
              data-testid={`${TEST_ID}-end-date`}
            />
          </div>
          <FormActions align="end">
            <Button variant="primary" onClick={handleView} data-testid={`${TEST_ID}-view-btn`}>
              <i className="fas fa-search" /> Xem
            </Button>
          </FormActions>
        </div>
      </div>

      {loading && (
        <div className={styles.loading} data-testid={`${TEST_ID}-loading`}>
          <Spin />
          <Text type="secondary">Đang tải báo cáo 13 tuần…</Text>
        </div>
      )}

      {!loading && loadError && (
        <div className={styles.empty} data-testid={`${TEST_ID}-error`}>
          <Text type="secondary">Không tải được dữ liệu. Thử Làm mới hoặc đổi ngày xem.</Text>
          <Button variant="primary" onClick={handleRefresh}>Thử lại</Button>
        </div>
      )}

      {!loading && !loadError && !data && (
        <div className={styles.empty} data-testid={`${TEST_ID}-empty`}>
          <Text type="secondary">Chưa có dữ liệu cho kỳ đã chọn.</Text>
        </div>
      )}

      {!loading && data && (
        <div className={styles.contentPanel} data-testid={`${TEST_ID}-content`}>
          <div className={styles.statsRow}>
            <div className={styles.statCard}>
              <span className={styles.statLabel}>Đầu kỳ (Tuần 1)</span>
              <span className={styles.statValue}>{fCompact(data.totalOpening)}</span>
            </div>
            <div className={styles.statCard}>
              <span className={styles.statLabel}>Cuối kỳ (Tuần 13)</span>
              <span className={styles.statValue}>{fCompact(data.closingAfter13Weeks)}</span>
            </div>
            <div className={styles.statCard}>
              <span className={styles.statLabel}>HĐKD thuần</span>
              <span className={`${styles.statValue} ${data.totalOperatingNet >= 0 ? styles.positive : styles.negative}`}>
                {fCompact(data.totalOperatingNet)}
              </span>
            </div>
            <div className={styles.statCard}>
              <span className={styles.statLabel}>Chi đầu tư</span>
              <span className={styles.statValue}>{fCompact(data.totalInvestingOutflow)}</span>
            </div>
            <div className={styles.statCard}>
              <span className={styles.statLabel}>Thiếu hụt lớn nhất</span>
              <span className={`${styles.statValue} ${maxGap > 0 ? styles.negative : styles.positive}`}>
                {fCompact(maxGap)}
              </span>
            </div>
            <div className={styles.statCard}>
              <span className={styles.statLabel}>Tuần thiếu hụt</span>
              <span className={gapWeeks > 0 ? `${styles.statValue} ${styles.warning}` : `${styles.statValue} ${styles.positive}`}>
                {gapWeeks} / 13 tuần
              </span>
            </div>
          </div>

          <div className={styles.chartCardFull} data-testid={`${TEST_ID}-chart`}>
            <div className={styles.chartCardHeader}>
              <h3 className={styles.chartTitle}>Dòng tiền 13 tuần — Hoạt động, đầu tư, tài chính</h3>
              <span className={styles.sectionBadge}>Biểu đồ kết hợp · {weeks.length} tuần</span>
            </div>
            {weeks.length > 0 ? (
              <ResponsiveContainer width="100%" height={320}>
                <BarChart data={chartRows}>
                  <CartesianGrid strokeDasharray="3 3" stroke="#f1f5f9" />
                  <XAxis dataKey="chartLabel" tick={{ fontSize: 11 }} />
                  <YAxis tickFormatter={chartCurrency} tick={{ fontSize: 11 }} />
                  <Tooltip formatter={(v: number) => fVnd(v)} />
                  <Legend />
                  <Bar dataKey="operatingNet" name="Hoạt động kinh doanh" fill="#10b981" radius={[4, 4, 0, 0]} stackId="a" />
                  <Bar dataKey="investingOutflow" name="Đầu tư" fill="#f59e0b" radius={[4, 4, 0, 0]} stackId="a" />
                  <Bar dataKey="financingInflow" name="Tài chính (vào)" fill="#3b82f6" radius={[4, 4, 0, 0]} stackId="a" />
                  <Bar dataKey="financingOutflow" name="Tài chính (ra)" fill="#ef4444" radius={[4, 4, 0, 0]} stackId="a" />
                </BarChart>
              </ResponsiveContainer>
            ) : (
              <Text type="secondary">Chưa có dữ liệu tuần trong kỳ.</Text>
            )}
          </div>

          <div className={styles.tableWrapper}>
            <table className={styles.table} data-testid={`${TEST_ID}-table`}>
              <thead>
                <tr>
                  <th>Tuần</th>
                  <th>Đầu kỳ</th>
                  <th>Thu hoạt động</th>
                  <th>Chi hoạt động</th>
                  <th>Đầu tư</th>
                  <th>Tài chính vào</th>
                  <th>Tài chính ra</th>
                  <th>Cuối kỳ</th>
                  <th>Thiếu hụt</th>
                </tr>
              </thead>
              <tbody>
                {weeks.length === 0 ? (
                  <tr>
                    <td colSpan={9}>
                      <Text type="secondary">Không có dòng tuần.</Text>
                    </td>
                  </tr>
                ) : (
                  weeks.map((w, i) => (
                    <tr
                      key={`${w.weekNumber}-${i}`}
                      className={w.fundingGap > 0 ? styles.rowGap : undefined}
                    >
                      <td style={{ fontWeight: 500 }}>{w.label}</td>
                      <td className={styles.colAmount}>{fVnd(w.openingBalance)}</td>
                      <td className={styles.colAmount} style={{ color: '#059669' }}>{fVnd(w.operatingInflow)}</td>
                      <td className={styles.colAmount} style={{ color: '#ef4444' }}>{fVnd(w.operatingOutflow)}</td>
                      <td className={styles.colAmount}>
                        {w.investingOutflow > 0 ? fVnd(w.investingOutflow) : '—'}
                      </td>
                      <td className={styles.colAmount} style={{ color: '#3b82f6' }}>
                        {w.financingInflow > 0 ? fVnd(w.financingInflow) : '—'}
                      </td>
                      <td className={styles.colAmount} style={{ color: '#ef4444' }}>
                        {w.financingOutflow > 0 ? fVnd(w.financingOutflow) : '—'}
                      </td>
                      <td className={styles.colAmount} style={{ fontWeight: 600 }}>{fVnd(w.closingBalance)}</td>
                      <td className={styles.colCenter}>
                        {w.fundingGap > 0
                          ? <span style={{ color: '#ef4444', fontWeight: 600 }}>{fVnd(w.fundingGap)}</span>
                          : <span style={{ color: '#10b981' }}>Đủ</span>}
                      </td>
                    </tr>
                  ))
                )}
              </tbody>
            </table>
          </div>

          {gapWeeks > 0 && (
            <div className={styles.hintCard} data-testid={`${TEST_ID}-gap-hint`}>
              <Text type="secondary">
                Có <strong>{gapWeeks}</strong> tuần thiếu hụt so với mức tiền tối thiểu
                {maxGap > 0 ? ` · thiếu lớn nhất ${fCompact(maxGap)}` : ''}.
              </Text>
            </div>
          )}
        </div>
      )}
    </div>
  );
};

export default ThirteenWeekCashflowPage;
